      --mXZkqc: @surface0;
      --EpFNW: @mantle;
      --XKMDxc: @mantle;
      --TSWZIb: @mantle;
      --tefdc5886c2f04483: @text;
      --te8f1ea4d4928be48: @text !important;
      --ta884a309a24f44f4: @subtext0 !important;
      --tdee01b39543f1cac: @base !important;
