      --t7d1a3050c2c1c0a5: @text !important;
      --t6a0469853a1a02c1: @text !important;
      --t5feec22832a0fdd6: @surface0 !important;
      --t342c96645d13ae13: @accent !important;
      --t6c7325fca9d536d4: @text !important;
      --tf7148cf5018d5074: @text !important;
