  body {
    background-color: var(--ctp-crust) !important;
    color: var(--ctp-text);
  }

  ::selection {
    background: color-mix(in srgb, var(--ctp-accent) 35%, transparent);
    color: var(--ctp-text);
  }

  /* Info bars ("Some content in this message has been blocked...") carry their colours in an
     inline style attribute, so they need a direct rule. */
  .fui-MessageBar[style*="background-color"] {
    background-color: var(--ctp-mantle) !important;
    border-color: var(--ctp-surface0) !important;
    color: var(--ctp-text) !important;
  }

  /* Email bodies are the sender's own HTML with hard-coded colours. Everything inside is
     flattened onto Mocha: backgrounds go transparent so base shows through, text becomes Mocha
     text, links blue. Images are left alone. Senders' own text colours are lost. */
  [aria-label="Message body"] {
    background-color: var(--ctp-base) !important;
    color: var(--ctp-text) !important;
  }

  [aria-label="Message body"] *:not(img, video, picture, canvas, svg, svg *) {
    background-color: transparent !important;
    background-image: none !important;
    color: var(--ctp-text) !important;
    border-color: var(--ctp-surface1) !important;
  }

  [aria-label="Message body"] a,
  [aria-label="Message body"] a * {
    color: var(--ctp-accent) !important;
  }

  /* Links the sender drew as buttons (their own background colour) keep a visible button shape. */
  [aria-label="Message body"] :is(a[style*="background"], a[bgcolor], td[bgcolor] > a, td[style*="background"] > a) {
    background-color: var(--ctp-surface0) !important;
    border-radius: 6px;
  }

  [aria-label="Message body"] hr {
    border-color: var(--ctp-surface1) !important;
  }

  * {
    scrollbar-color: var(--ctp-surface2) transparent;
  }
}

