/*
  Colours
  -------
  Every rule below uses the 26 Catppuccin roles as CSS variables (--ctp-base, --ctp-text,
  --ctp-surface0, ...) plus --ctp-accent. They are set once, in the #palette mixin at the top
  of the @-moz-document block, from the Catppuccin library: pick the flavour and accent in
  Stylus's style settings.

  Using another theme (Gruvbox, Nord, Tokyo Night, ...): replace the body of #palette with your
  own colours for the same roles, e.g.

    #palette() {
      --ctp-base: #282828;   --ctp-mantle: #1d2021;  --ctp-crust: #141617;
      --ctp-surface0: #3c3836; --ctp-surface1: #504945; --ctp-surface2: #665c54;
      --ctp-overlay0: #7c6f64; --ctp-overlay1: #928374; --ctp-overlay2: #a89984;
      --ctp-subtext0: #bdae93; --ctp-subtext1: #d5c4a1; --ctp-text: #ebdbb2;
      --ctp-accent: #83a598;  ...and the accents (red, green, yellow, blue, mauve, ...)
    }

  base/mantle/crust are the page backgrounds (mantle and crust darker), surface0-2 raised
  surfaces and borders, overlay0-2 muted text, subtext/text the text colours.
*/

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("teams.microsoft.com"), domain("teams.cloud.microsoft"), domain("teams.live.com") {

  :root {
    #palette();
  }

  #palette() {
    #lib.palette();
    #lib.css-variables();
    --ctp-accent: @accent;

    // Message loading skeleton: Teams draws it as an inline SVG, so it is rebuilt from the palette
    // (incoming bubbles surface0, your own messages accent-tinted base, bars and avatars surface1).
    @skel-bubble: escape(~"@{surface0}");
    @skel-own: escape(~"@{skel-own-c}");
    @skel-own-c: mix(@accent, @base, 15%);
    @skel-bar: escape(~"@{surface1}");
    [data-testid="vl-placeholders"] {
      background-image: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='100%' height='340px'><svg width='40%' x='42px' y='16px'><rect width='100%' height='52px' rx='4px' ry='4px' fill='@{skel-bubble}' /><svg x='16px' y='12px'><rect width='60%' height='10px' rx='2px' ry='2px' fill='@{skel-bar}' /><rect width='80%' height='10px' y='18px' rx='2px' ry='2px' fill='@{skel-bar}' /></svg></svg><circle cx='16px' cy='42px' r='16px' fill='@{skel-bar}' /><svg width='70%' x='42px' y='70px'><rect width='100%' height='32px' rx='4px' ry='4px' fill='@{skel-bubble}'/><svg x='16px' y='12px'><rect width='90%' height='10px' rx='2px' ry='2px' fill='@{skel-bar}' /></svg></svg><svg width='60%' x='calc(40% - 74px)' y='118px'><rect width='100%' height='52px' rx='4px' ry='4px' fill='@{skel-own}' /><svg x='16px' y='12px'><rect width='60%' height='10px' rx='2px' ry='2px' fill='@{skel-bar}' /><rect width='80%' height='10px' y='18px' rx='2px' ry='2px' fill='@{skel-bar}' /></svg></svg><svg width='70%' x='calc(30% - 74px)' y='172px'><rect width='100%' height='32px' rx='4px' ry='4px' fill='@{skel-own}'/><svg x='16px' y='12px'><rect width='90%' height='10px' rx='2px' ry='2px' fill='@{skel-bar}' /></svg></svg><svg width='45%' x='42px' y='220px'><rect width='100%' height='52px' rx='4px' ry='4px' fill='@{skel-bubble}' /><svg x='16px' y='12px'><rect width='60%' height='10px' rx='2px' ry='2px' fill='@{skel-bar}' /><rect width='80%' height='10px' y='18px' rx='2px' ry='2px' fill='@{skel-bar}' /></svg></svg><circle cx='16px' cy='246px' r='16px' fill='@{skel-bar}' /><svg width='45%' x='calc(55% - 74px)' y='288px'><rect width='100%' height='52px' rx='4px' ry='4px' fill='@{skel-own}' /><svg x='16px' y='12px'><rect width='60%' height='10px' rx='2px' ry='2px' fill='@{skel-bar}' /><rect width='80%' height='10px' y='18px' rx='2px' ry='2px' fill='@{skel-bar}' /></svg></svg></svg>") !important;
    }
  }


  /* Teams injects its Fluent UI theme at runtime onto <html> and every Fluent provider element.
     An !important stylesheet value beats those in any Teams theme (light, dark, classic). */
  :root,
  .fui-FluentProvider,
  [class*="fui-FluentProvider"] {
    color-scheme: dark !important;

    /* Teams shell: title bar and loading screen */
    --themeTitleBarBackgroundColor: var(--ctp-crust) !important;
    --themeTitleBarColor: var(--ctp-subtext0) !important;
    --themeTitleBarButtonColor: var(--ctp-subtext0) !important;
    --themeTitleBarButtonHoverBackgroundColor: var(--ctp-surface0) !important;
    --themeTitleBarButtonHoverColor: var(--ctp-text) !important;
