    /* Message composer (CKEditor) */
    --ck-color-base-background: transparent !important;
    --ck-color-base-border: var(--ctp-surface1) !important;
    --ck-color-base-text: var(--ctp-text) !important;
    --ck-color-text: var(--ctp-text) !important;
    --ck-color-engine-placeholder-text: var(--ctp-overlay1) !important;
