  body {
    background-color: var(--ctp-crust) !important;
    color: var(--ctp-text);
  }

  /* Panes Teams paints with its own colours instead of Fluent tokens. Hooked by data-tid /
     data-testid, which stay stable while the generated class names change. */
  :is([data-tid], [data-testid]):is(
    [data-tid="app-layout-area--mid-nav"],
    [data-tid="app-layout-area--sub-nav"],
    [data-tid="simple-collab-rail"], [data-testid="simple-collab-rail"],
    [data-testid="simple-collab-left-rail-header"],
    [data-testid="simple-collab-left-rail-sticky-filter-v2"],
    [data-tid="activity-list-container"], [data-testid="activity-list-container"],
    [data-tid="default-feed-header"], [data-testid="default-feed-header"],
    [data-testid="filter-toolbar"]
  ) {
    background-color: var(--ctp-mantle) !important;
  }

  :is([data-tid], [data-testid]):is(
    [data-tid="app-layout-area--header"],
    [data-tid="entity-header"], [data-testid="entity-header"],
    [data-tid="app-layout-area--main"],
    [data-tid="app-layout-area--end"]
  ) {
    background-color: var(--ctp-base) !important;
  }

  [data-tid="app-layout-area--header"] {
    border-bottom: 1px solid var(--ctp-surface0) !important;
  }

  [data-tid="app-layout-area--nav"],
  [data-tid="app-bar-wrapper"],
  [data-tid="app-layout-area--title-bar"],
  [data-tid="title-bar"] {
    background-color: var(--ctp-crust) !important;
  }

  /* Teams draws the divider under the title bar with a token that maps to the text colour, which
     turns it into a bright line; whichever side draws it, it becomes a quiet surface0 line. */
  [data-tid="app-layout-area--title-bar"],
  [data-tid="title-bar"],
  [data-tid="pre-core-title-bar"] {
    border-bottom-color: var(--ctp-surface0) !important;
    box-shadow: none !important;
  }
  [data-tid="app-layout-area--nav"],
  [data-tid="app-layout-area--mid-nav"],
  [data-tid="app-layout-area--sub-nav"],
  [data-tid="app-layout-area--unified-areas"],
  [data-tid="app-layout-area--header"],
  [data-tid="app-layout-area--main"] {
    border-top-color: var(--ctp-surface0) !important;
  }
  [data-tid="app-layout-area--title-bar"]::after,
  [data-tid="title-bar"]::after,
  [data-tid="app-layout-area--title-bar"]::before,
  [data-tid="title-bar"]::before {
    background-color: var(--ctp-surface0) !important;
    border-color: var(--ctp-surface0) !important;
  }


  ::selection {
    background: color-mix(in srgb, var(--ctp-accent) 35%, transparent);
    color: var(--ctp-text);
  }

  * {
    scrollbar-color: var(--ctp-surface2) transparent;
  }
}

