@preprocessor   less
@var select flavor "Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue*", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender"]
==/UserStyle== */

/*
  Colours
  -------
  Every rule below uses the 26 Catppuccin roles as CSS variables (--ctp-base, --ctp-text,
  --ctp-surface0, ...) plus --ctp-accent. They are set once, in the #palette mixin at the top
  of the @-moz-document block, from the Catppuccin library: pick the flavour and accent in
  Stylus's style settings.

  Using another theme (Gruvbox, Nord, Tokyo Night, ...): replace the body of #palette with your
  own colours for the same roles, e.g.

    #palette() {
      --ctp-base: #282828;   --ctp-mantle: #1d2021;  --ctp-crust: #141617;
      --ctp-surface0: #3c3836; --ctp-surface1: #504945; --ctp-surface2: #665c54;
      --ctp-overlay0: #7c6f64; --ctp-overlay1: #928374; --ctp-overlay2: #a89984;
      --ctp-subtext0: #bdae93; --ctp-subtext1: #d5c4a1; --ctp-text: #ebdbb2;
      --ctp-accent: #83a598;  ...and the accents (red, green, yellow, blue, mauve, ...)
    }

  base/mantle/crust are the page backgrounds (mantle and crust darker), surface0-2 raised
  surfaces and borders, overlay0-2 muted text, subtext/text the text colours.
*/

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("music.youtube.com") {

  :root {
    #palette();
  }

  #palette() {
    #lib.palette();
    #lib.css-variables();
    --ctp-accent: @accent;
  }


  /* YouTube's colour tokens: the yt-sys set it reads today, the older yt-spec / yt-deprecated names,
     live chat, Polymer paper widgets and the hashed --t* aliases. YouTube also sets them on nested
     [dark]/[light] elements, so those are matched too. Generated from YouTube's own stylesheets. */
  :root,
  [dark],
  [light],
  [darker-dark-theme],
  [system-icons],
  [color-version] {
    color-scheme: dark !important;
    --ytd-searchbox-legacy-button-icon-color: var(--ctp-text) !important;
    --ytd-searchbox-border-color: var(--ctp-surface1) !important;
    --ytd-searchbox-legacy-border-color: var(--ctp-surface1) !important;
    --ytd-searchbox-legacy-border-shadow-color: transparent !important;
    --ytd-searchbox-legacy-button-color: var(--ctp-surface0) !important;
    --ytd-searchbox-legacy-button-border-color: var(--ctp-surface1) !important;
    --ytd-searchbox-legacy-button-focus-color: var(--ctp-surface1) !important;
    --ytd-searchbox-legacy-button-hover-color: var(--ctp-surface1) !important;
    --ytd-searchbox-legacy-button-hover-border-color: var(--ctp-surface1) !important;
    --ytd-searchbox-background: var(--ctp-base) !important;
    --ytd-searchbox-text-color: var(--ctp-text) !important;
    --yt-sys-color-baseline--static-ad-yellow: var(--ctp-yellow) !important;
    --yt-sys-color-baseline--background-warning: color-mix(in srgb, var(--ctp-peach) 21%, transparent) !important;
    --yt-sys-color-baseline--background-complete: color-mix(in srgb, var(--ctp-green) 21%, transparent) !important;
    --yt-sys-color-baseline--text-warning: var(--ctp-peach) !important;
    --yt-sys-color-baseline--text-complete: var(--ctp-green) !important;
    --yt-sys-color-baseline--text-error: var(--ctp-red) !important;
    --yt-sys-color-baseline--base-background: var(--ctp-base) !important;
    --yt-sys-color-baseline--raised-background: var(--ctp-mantle) !important;
    --yt-sys-color-baseline--menu-background: var(--ctp-mantle) !important;
    --yt-sys-color-baseline--inverted-background: var(--ctp-text) !important;
    --yt-sys-color-baseline--inverted-background-hover: var(--ctp-subtext1) !important;
    --yt-sys-color-baseline--additive-background: color-mix(in srgb, var(--ctp-text) 10%, transparent) !important;
