  .ytp-bound-time-left,.ytp-bound-time-right { background-color: color-mix(in srgb, var(--ctp-surface0) 90%, transparent); color: var(--ctp-text); }
  .ytp-bound-time-left:after { border-color: color-mix(in srgb, var(--ctp-surface0) 90%, transparent) transparent transparent transparent; }
  .ytp-bound-time-right:after { border-color: transparent color-mix(in srgb, var(--ctp-surface0) 90%, transparent) transparent transparent; }
  .ytp-timed-marker { background-color: var(--ctp-text); }
  .ytp-progress-linear-live-buffer { background: var(--ctp-accent); }
  .ytp-load-progress.ytp-fast-load { background: color-mix(in srgb, var(--ctp-teal) 30%, var(--ctp-base)); }
  .ytp-play-progress { background: -webkit-gradient(linear,left top,right top,color-stop(80%,var(--ctp-accent)),to(var(--ctp-lavender))); background: -webkit-linear-gradient(left,var(--ctp-accent) 80%,var(--ctp-lavender)); background: linear-gradient(90deg,var(--ctp-accent) 80%,var(--ctp-lavender)); }
  .ytp-unified-seek-active .ytp-unified-seek-wrapper { background: -webkit-gradient(linear,left top,right top,color-stop(80%,var(--ctp-accent)),to(var(--ctp-lavender))); background: -webkit-linear-gradient(left,var(--ctp-accent) 80%,var(--ctp-lavender)); background: linear-gradient(90deg,var(--ctp-accent) 80%,var(--ctp-lavender)); }
  .ytp-settings-button.ytp-3d-badge-grey:after { background-color: var(--ctp-overlay0); }
  .ytp-settings-button.ytp-hbr-quality-badge:after,.ytp-settings-button.ytp-hdr-quality-badge:after { border-color: var(--ctp-accent); }
  .ytp-popup { background: color-mix(in srgb, var(--ctp-surface0) 90%, transparent); }
  .ytp-share-panel-close path { fill: var(--ctp-subtext0); }
  .ytp-share-panel-include-playlist { color: var(--ctp-subtext0); }
  .ytp-slider-handle { background: var(--ctp-text); }
  .ytp-slider-handle:before { background: var(--ctp-text); }
  .ytp-spinner-circle { border-color: var(--ctp-text) var(--ctp-text) transparent; }
  .ytp-sfn { background: color-mix(in srgb, var(--ctp-surface0) 80%, transparent); }
  .ytp-storyboard-framepreview-timestamp { color: var(--ctp-text); }
  .ytp-sb-subscribe,a.ytp-sb-subscribe { background-color: var(--ctp-text); }
  .ytp-shorts-mode .ytp-sb-subscribe,.ytp-shorts-mode a.ytp-sb-subscribe { background-color: var(--ctp-text); }
  .ytp-shorts-mode .ytp-sb-unsubscribe { color: var(--ctp-text); }
  .ytp-sb-subscribe.ytp-sb-disabled,.ytp-sb-unsubscribe.ytp-sb-disabled { background-color: var(--ctp-red); }
  .ytp-sb.ytp-sb-classic { background-color: var(--ctp-text); }
  .ytp-sb-classic .ytp-sb-subscribe { border: 1px solid var(--ctp-accent); }
  .ytp-sb-classic .ytp-sb-unsubscribe { border: 1px solid var(--ctp-text); }
  .ytp-sb-classic .ytp-sb-count { border: 1px solid var(--ctp-text); }
  .ytp-sb-classic .ytp-sb-subscribe .ytp-sb-count,.ytp-sb-classic .ytp-sb-unsubscribe { background-color: var(--ctp-text); }
  .ytp-sb-classic .ytp-sb-subscribe .ytp-sb-text { background-color: var(--ctp-accent); }
  .ytp-sb-classic .ytp-sb-count,.ytp-sb-classic .ytp-sb-unsubscribe .ytp-sb-text { background-color: var(--ctp-text); color: var(--ctp-overlay1); }
  .caption-edit { background: color-mix(in srgb, var(--ctp-base) 75%, transparent); }
  .ytp-suggested-action-badge:hover { background-color: color-mix(in srgb, var(--ctp-surface0) 95%, transparent); }
  .ytp-suggested-action-badge-img { background: var(--ctp-text); }
  .ytp-suggested-action-more-products-icon { background-color: var(--ctp-text); }
  .ytp-featured-product-thumbnail { background: var(--ctp-text); }
  .ytp-featured-product-exclusive-badge { background: -webkit-gradient(linear,left top,right top,from(color-mix(in srgb, var(--ctp-mauve) 30%, var(--ctp-base))),color-stop(var(--ctp-mauve)),to(var(--ctp-pink))); background: -webkit-linear-gradient(left,color-mix(in srgb, var(--ctp-mauve) 30%, var(--ctp-base)),var(--ctp-mauve),var(--ctp-pink)); background: linear-gradient(90deg,color-mix(in srgb, var(--ctp-mauve) 30%, var(--ctp-base)),var(--ctp-mauve),var(--ctp-pink)); }
  .ytp-delhi-modern-with-luminosity.ytp-delhi-modern .ytp-time-wrapper:not(.ytp-miniplayer-ui *) { background: color-mix(in srgb, var(--ctp-surface2) 60%, transparent); }
  .ytp-delhi-modern-with-difference.ytp-delhi-modern .ytp-time-wrapper:not(.ytp-miniplayer-ui *) { background: color-mix(in srgb, var(--ctp-surface2) 60%, transparent); }
  .ytp-delhi-modern-with-exclusion.ytp-delhi-modern .ytp-time-wrapper:not(.ytp-miniplayer-ui *) { background: color-mix(in srgb, var(--ctp-surface2) 60%, transparent); }
  .ytp-time-current,.ytp-time-duration,.ytp-time-separator { color: var(--ctp-text); }
  .ytp-live-badge:before { background: var(--ctp-overlay1); }
  .ytp-delhi-modern-with-luminosity.ytp-delhi-modern .ytp-clip .ytp-clip-watch-full-video-button { background: color-mix(in srgb, var(--ctp-surface2) 60%, transparent); }
  .ytp-delhi-modern-with-difference.ytp-delhi-modern .ytp-clip .ytp-clip-watch-full-video-button { background: color-mix(in srgb, var(--ctp-surface2) 60%, transparent); }
  .ytp-delhi-modern-with-exclusion.ytp-delhi-modern .ytp-clip .ytp-clip-watch-full-video-button { background: color-mix(in srgb, var(--ctp-surface2) 60%, transparent); }
  .ytp-time-clip-icon svg { fill: var(--ctp-text); }
  .ytp-menuitem[aria-disabled=true] { color: var(--ctp-overlay2); }
  .ytp-menuitem[aria-disabled=true] path { fill: var(--ctp-overlay2); }
  .ytp-menuitem-toggle-checkbox:after { background-color: var(--ctp-subtext1); }
  .ytp-menuitem[aria-checked=true] .ytp-menuitem-toggle-checkbox:after { background-color: var(--ctp-text); }
  .ytp-tooltip.ytp-preview { background-color: color-mix(in srgb, var(--ctp-surface0) 90%, transparent); }
  .ytp-tooltip-bottom-text { background-color: color-mix(in srgb, var(--ctp-surface0) 90%, transparent); }
  .ytp-tooltip-opaque .ytp-tooltip-bottom-text { background-color: var(--ctp-surface0); }
  .ytp-tooltip.ytp-preview:not(.ytp-text-detail) { background-color: var(--ctp-text); }
  .ytp-tooltip.ytp-text-detail.ytp-preview.ytp-has-duration .ytp-tooltip-duration { background-color: color-mix(in srgb, var(--ctp-surface0) 90%, transparent); }
  .ytp-tooltip.ytp-text-detail .ytp-tooltip-title { color: var(--ctp-subtext0); }
  .ytp-unmute-inner { background-color: var(--ctp-text); border-bottom: 1px solid var(--ctp-text); }
  .ytp-unmute-animated .ytp-unmute-icon { background-color: var(--ctp-text); border-bottom: 1px solid var(--ctp-text); }
  .ytp-unmute-animated .ytp-unmute-box { background-color: var(--ctp-text); border-bottom: 1px solid var(--ctp-text); }
  .ytp-user-info-panel { background: color-mix(in srgb, var(--ctp-surface0) 80%, transparent); }
  .ytp-user-info-panel-login { color: var(--ctp-accent); }
  .ytp-video-menu-item-author { color: var(--ctp-subtext1); }
  .ytp-volume-slider-handle { background: var(--ctp-text); }
  .ytp-volume-slider-handle:before { background: var(--ctp-text); }
  .ytp-continue-watching-button.ytp-watch-on-youtube-button { background-color: var(--ctp-text); color: var(--ctp-base); }
  .ytp-continue-watching-button.ytp-watch-on-youtube-button:hover { background-color: var(--ctp-text); color: var(--ctp-base); }
  .ytp-watch-on-youtube-button:focus { border: 2px solid var(--ctp-text); }
  .ytp-continue-watching-button.ytp-watch-on-youtube-button:focus { border: 2px solid var(--ctp-text); background-color: var(--ctp-base); }
  .ytp-watch-again-on-youtube-endscreen-more-videos-container .ytp-more-videos-view { background: color-mix(in srgb, var(--ctp-surface0) 90%, transparent); }
  .ytp-drawer-open-button:after { border-right-color: var(--ctp-subtext0); }

  /* ---- Hand-written fixes ---- */

  html, body, ytmusic-app {
    background-color: var(--ctp-base) !important;
  }

  /* Browse pages (home, explore, library, albums, artists) sit on the same fixed Mocha glow as the
     player page. Music's own backgrounds are switched off: the blurred cover art (its colours clash
     with Mocha) and the 60%-black gradient, which Music sizes to half a screen without no-repeat, so
     on anything but pure black it repeats as dark bands. */
  ytmusic-app-layout, #layout.ytmusic-app {
    background: var(--ctp-base) !important;
  }
  /* Every layer between the app and the cards stays transparent. Some of these get their background
     from styles Music injects at runtime, so they are listed whether or not its stylesheet paints them;
     a single solid layer here covers the glow from the chip row down and leaves a lone strip above it. */
  #content.ytmusic-app-layout, ytmusic-app-layout > #content, ytmusic-app-layout > [slot=content],
  ytmusic-browse-response, ytmusic-browse-response > div, #content-wrapper.ytmusic-browse-response,
  ytmusic-search-page, ytmusic-tabbed-search-results-renderer, ytmusic-tabbed-browse-renderer,
  ytmusic-section-list-renderer, ytmusic-section-list-renderer > div,
  #header.ytmusic-section-list-renderer, #contents.ytmusic-section-list-renderer,
  ytmusic-chip-cloud-renderer, ytmusic-carousel-shelf-renderer, ytmusic-immersive-carousel-shelf-renderer,
  ytmusic-shelf-renderer, ytmusic-grid-renderer, ytmusic-item-section-renderer, ytmusic-card-shelf-renderer,
  ytmusic-description-shelf-renderer, ytmusic-tastebuilder-shelf-renderer, ytmusic-tab-renderer,
  ytmusic-carousel, #items.ytmusic-carousel {
    background: transparent !important;
  }
  /* Sticky section headers get a frosted bar once they stick, instead of an opaque one */
  ytmusic-item-section-renderer.stuck #header.ytmusic-item-section-renderer {
    background: color-mix(in srgb, var(--ctp-mantle) 78%, transparent) !important;
    backdrop-filter: blur(24px) !important;
  }
  .background-gradient.ytmusic-immersive-carousel-shelf-renderer,
  .gradient-container.ytmusic-immersive-header-renderer {
    background-image: none !important;
  }

  /* Top-of-page glow, in place of Music's blurred-cover one: mauve and blue washes across the top that
     fade into base. It sits on Music's own gradient layer (above the page wrappers, so nothing covers
     it), scrolls with the page, and does not repeat. */
  ytmusic-browse-response > .background-gradient.ytmusic-browse-response,
  ytmusic-browse-response .background-gradient.ytmusic-browse-response {
    background-color: transparent !important;
    background-image:
      radial-gradient(60% 75% at 22% 0%, color-mix(in srgb, var(--ctp-mauve) 22%, transparent), transparent 70%),
      radial-gradient(55% 70% at 78% 0%, color-mix(in srgb, var(--ctp-accent) 20%, transparent), transparent 70%),
      radial-gradient(40% 50% at 50% 10%, color-mix(in srgb, var(--ctp-pink) 8%, transparent), transparent 70%) !important;
    background-size: 100% 85vh !important;
    background-repeat: no-repeat !important;
    background-position: top center !important;
  }
  ytmusic-browse-response .immersive-background, ytmusic-browse-response ytmusic-fullbleed-thumbnail-renderer,
  .immersive-background.ytmusic-card-shelf-renderer ytmusic-fullbleed-thumbnail-renderer,
  ytmusic-immersive-header-renderer ytmusic-fullbleed-thumbnail-renderer {
    display: none !important;
  }
  .immersive-background.ytmusic-card-shelf-renderer::before {
    background-image: none !important;
  }

  /* Player page glow. Desktop Music has no album-art glow here (only the mobile layout does), and CSS
     cannot read colours out of the cover, so this is a fixed Mocha one: blue, mauve and sapphire
     washes fading into base. */
  ytmusic-player-page, #player-page {
    background:
      radial-gradient(55% 50% at 32% 38%, color-mix(in srgb, var(--ctp-accent) 20%, transparent), transparent 72%),
      radial-gradient(45% 45% at 78% 72%, color-mix(in srgb, var(--ctp-mauve) 15%, transparent), transparent 72%),
      radial-gradient(40% 40% at 12% 88%, color-mix(in srgb, var(--ctp-sapphire) 12%, transparent), transparent 72%),
      radial-gradient(35% 35% at 88% 12%, color-mix(in srgb, var(--ctp-lavender) 10%, transparent), transparent 72%),
      var(--ctp-base) !important;
  }
  ytmusic-player-page .side-panel, ytmusic-player-page #side-panel, ytmusic-player-page .content,
  ytmusic-player-page #main-panel, ytmusic-player-page ytmusic-tab-renderer {
    background: transparent !important;
  }
  /* Letterbox around videos blends into the glow instead of a hard black box */
  ytmusic-player-page #player, ytmusic-player-page ytmusic-player, ytmusic-player #song-video,
  ytmusic-player .html5-video-player {
    background: transparent !important;
  }

  ::selection {
    background: color-mix(in srgb, var(--ctp-accent) 35%, transparent);
    color: var(--ctp-text);
  }

  * {
    scrollbar-color: var(--ctp-surface2) transparent;
  }
  ::-webkit-scrollbar-thumb { background-color: var(--ctp-surface2) !important; }
  ::-webkit-scrollbar-thumb:hover { background-color: var(--ctp-overlay0) !important; }

  /* Top bar, side menu, player bar */
  ytmusic-nav-bar {
    background: transparent !important;
  }
  #nav-bar-background, #nav-bar-background.ytmusic-app-layout {
    background: color-mix(in srgb, var(--ctp-mantle) 82%, transparent) !important;
    backdrop-filter: blur(24px) !important;
    border-color: var(--ctp-surface0) !important;
  }
  #mini-guide-background, #mini-guide-background.ytmusic-app-layout,
  ytmusic-guide-renderer, #guide-wrapper.ytmusic-app, #guide-content, #mini-guide {
    background: var(--ctp-mantle) !important;
    border-color: var(--ctp-surface0) !important;
  }
  ytmusic-player-bar, #player-bar-background, #player-bar-background.ytmusic-app-layout {
    background: var(--ctp-mantle) !important;
  }
  ytmusic-app-layout[player-fullscreened] > [slot=player-bar] { background: transparent !important; }
  tp-yt-paper-item.ytmusic-guide-entry-renderer:hover,
  ytmusic-guide-entry-renderer:not([is-primary]) tp-yt-paper-item:hover {
    background-color: var(--ctp-surface0) !important;
  }
  ytmusic-guide-entry-renderer[active] tp-yt-paper-item, ytmusic-guide-entry-renderer[active] .item {
    background-color: var(--ctp-surface0) !important;
  }

  /* Logo: YouTube red becomes the accent */
  [fill="red"], [fill="#F00"], [fill="#f00"], [fill="#FF0000"], [fill="#ff0000"],
  [fill="#f03"], [fill="#F03"], [fill="#FF0033"], [fill="#ff0033"] {
    fill: var(--ctp-accent) !important;
  }
  ytmusic-logo [fill="white"], ytmusic-logo [fill="#FFF"], ytmusic-logo [fill="#fff"], ytmusic-logo [fill="#FFFFFF"] {
    fill: var(--ctp-text) !important;
  }

  /* Progress bar: played part and knob in the accent, the rest a quiet surface */
  #progress-bar, #progress-bar.ytmusic-player-bar, tp-yt-paper-slider {
    --paper-slider-active-color: var(--ctp-accent) !important;
    --paper-slider-knob-color: var(--ctp-accent) !important;
    --paper-slider-knob-start-color: var(--ctp-accent) !important;
    --paper-slider-knob-start-border-color: var(--ctp-accent) !important;
    --paper-slider-secondary-color: var(--ctp-surface2) !important;
    --paper-slider-container-color: var(--ctp-surface1) !important;
    --paper-progress-active-color: var(--ctp-accent) !important;
    --paper-progress-secondary-color: var(--ctp-surface2) !important;
    --paper-progress-container-color: var(--ctp-surface1) !important;
  }
  #primaryProgress.tp-yt-paper-progress { background: var(--ctp-accent) !important; }
  #secondaryProgress.tp-yt-paper-progress { background: var(--ctp-surface2) !important; }
  .slider-knob-inner.tp-yt-paper-slider { background-color: var(--ctp-accent) !important; border-color: var(--ctp-accent) !important; }

  /* Player page tabs (Up next / Lyrics / Related) */
  tp-yt-paper-tabs.ytmusic-player-page {
    --paper-tabs-selection-bar-color: var(--ctp-accent) !important;
    border-bottom-color: var(--ctp-surface0) !important;
  }
  tp-yt-paper-tab.ytmusic-player-page { color: var(--ctp-subtext0) !important; }
  tp-yt-paper-tab.iron-selected.ytmusic-player-page { color: var(--ctp-text) !important; }
  ytmusic-player-queue-item[play-button-state=playing], ytmusic-player-queue-item[play-button-state=paused],
  ytmusic-player-queue-item[play-button-state=loading], ytmusic-player-queue-item[selected] {
    background-color: var(--ctp-surface0) !important;
  }
  ytmusic-player-queue-item:hover { background-color: color-mix(in srgb, var(--ctp-surface0) 60%, transparent) !important; }

  /* Chips (All / Familiar / Discover ...) */
  /* Translucent like Music's own, so chips stay a step lighter than the glow behind them */
  ytmusic-chip-cloud-chip-renderer a.ytmusic-chip-cloud-chip-renderer {
    background: color-mix(in srgb, var(--ctp-text) 10%, transparent) !important;
    border: 1px solid color-mix(in srgb, var(--ctp-text) 14%, transparent) !important;
    color: var(--ctp-text) !important;
  }
  ytmusic-chip-cloud-chip-renderer a.ytmusic-chip-cloud-chip-renderer:hover {
    background: color-mix(in srgb, var(--ctp-text) 18%, transparent) !important;
  }
  ytmusic-chip-cloud-chip-renderer[is-selected] a.ytmusic-chip-cloud-chip-renderer,
  ytmusic-chip-cloud-chip-renderer.iron-selected a.ytmusic-chip-cloud-chip-renderer {
    background: var(--ctp-accent) !important;
    border-color: var(--ctp-accent) !important;
    color: var(--ctp-crust) !important;
  }

  /* Buttons: white filled pills (Save, Play, Shuffle) become the accent */
  .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--filled,
  .ytSpecButtonShapeNextMono.ytSpecButtonShapeNextFilled,
  .yt-spec-button-shape-next--call-to-action.yt-spec-button-shape-next--filled,
  .ytSpecButtonShapeNextCallToAction.ytSpecButtonShapeNextFilled {
    background-color: var(--ctp-accent) !important;
    color: var(--ctp-crust) !important;
  }
  .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--tonal,
  .ytSpecButtonShapeNextMono.ytSpecButtonShapeNextTonal {
    background-color: var(--ctp-surface0) !important;
    color: var(--ctp-text) !important;
  }
  .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--outline,
  .ytSpecButtonShapeNextMono.ytSpecButtonShapeNextOutline {
    border-color: var(--ctp-surface2) !important;
    color: var(--ctp-text) !important;
  }

  /* Search */
  ytmusic-search-box #input-box, ytmusic-search-box .search-box, ytmusic-search-box[opened] #input-box,
  ytmusic-search-box[is-bauhaus-sidenav-enabled] .search-box {
    background: color-mix(in srgb, var(--ctp-text) 8%, transparent) !important;
    border: 1px solid color-mix(in srgb, var(--ctp-text) 16%, transparent) !important;
    color: var(--ctp-text) !important;
  }
  ytmusic-search-box[opened] #input-box, ytmusic-search-box[opened] .search-box,
  ytmusic-search-box:focus-within .search-box {
    background: var(--ctp-mantle) !important;
    border-color: var(--ctp-accent) !important;
  }
  ytmusic-search-box input, ytmusic-search-box #input { color: var(--ctp-text) !important; }
  ytmusic-search-suggestions-section, #suggestion-list.ytmusic-search-box {
    background: var(--ctp-mantle) !important;
  }

  /* Menus and dialogs */
  ytmusic-menu-popup-renderer, tp-yt-paper-listbox, ytmusic-multi-page-menu-renderer,
  tp-yt-paper-dialog, ytmusic-dialog, ytmusic-popup-container tp-yt-iron-dropdown #contentWrapper > * {
    background-color: var(--ctp-mantle) !important;
  }
  ytmusic-menu-navigation-item-renderer:hover, ytmusic-menu-service-item-renderer:hover,
  ytmusic-toggle-menu-service-item-renderer:hover, tp-yt-paper-item:hover {
    background-color: var(--ctp-surface0) !important;
  }

  /* Switches */
  .ytSwitchShapeTrack { background-color: var(--ctp-surface2) !important; }
  .ytSwitchShapeTrackActive { background-color: var(--ctp-accent) !important; }
  .ytSwitchShapeKnob { background-color: var(--ctp-text) !important; }
}

