  /* ---- Hand-written fixes ---- */

  html, body {
    background-color: var(--ctp-base) !important;
  }

  /* Page glow: fixed Mocha washes behind everything (blue, mauve, sapphire, lavender into base).
     The page containers above it go transparent so it shows through; cards, menus and the player
     keep their own surfaces. */
  ytd-app {
    background:
      radial-gradient(50% 45% at 22% 18%, color-mix(in srgb, var(--ctp-accent) 14%, transparent), transparent 72%),
      radial-gradient(45% 45% at 85% 30%, color-mix(in srgb, var(--ctp-mauve) 11%, transparent), transparent 72%),
      radial-gradient(45% 40% at 70% 92%, color-mix(in srgb, var(--ctp-sapphire) 9%, transparent), transparent 72%),
      radial-gradient(35% 35% at 8% 80%, color-mix(in srgb, var(--ctp-lavender) 8%, transparent), transparent 72%),
      var(--ctp-base) !important;
    background-attachment: fixed !important;
  }
  ytd-page-manager, #page-manager, ytd-browse, ytd-search, ytd-watch-flexy, #columns.ytd-watch-flexy,
  ytd-two-column-browse-results-renderer, ytd-two-column-search-results-renderer, ytd-rich-grid-renderer,
  ytd-section-list-renderer, ytd-item-section-renderer, ytd-rich-section-renderer, ytd-shelf-renderer,
  ytd-playlist-video-list-renderer, ytd-tabbed-page-header, #contents.ytd-rich-grid-renderer {
    background: transparent !important;
  }

  ::selection {
    background: color-mix(in srgb, var(--ctp-accent) 35%, transparent);
    color: var(--ctp-text);
  }

  * {
    scrollbar-color: var(--ctp-surface2) transparent;
  }

  /* Top bar and left guide */
  /* Frosted: one translucent, blurred layer. #frosted-glass already spans the top bar and, when it is
     shown, the chip row (56px / 112px), so both read as one bar; the masthead's own background and the
     chip row stay transparent on top of it instead of stacking a second blur. */
  ytd-masthead {
    background: transparent !important;
  }
  #frosted-glass, #frosted-glass.ytd-app, #frosted-glass.with-chipbar, #frosted-glass.without-chipbar,
  #frosted-glass.loading-with-chipbar, #frosted-glass.loading-without-chipbar, #frosted-glass.none {
    background: color-mix(in srgb, var(--ctp-base) 78%, transparent) !important;
    backdrop-filter: blur(24px) !important;
  }
  tp-yt-app-drawer #contentContainer, #guide-content, ytd-mini-guide-renderer, #guide-wrapper {
    background: color-mix(in srgb, var(--ctp-mantle) 72%, transparent) !important;
    backdrop-filter: blur(24px) !important;
  }
  ytd-guide-entry-renderer[active] tp-yt-paper-item, ytd-guide-entry-renderer[active] {
    background-color: var(--ctp-surface0) !important;
  }

  /* Page load bar */
  #progress.yt-page-navigation-progress, yt-page-navigation-progress #progress {
    background: var(--ctp-accent) !important;
  }

  /* Logo: YouTube red becomes the accent, the play triangle stays dark */
  [fill="red"], [fill="#F00"], [fill="#f00"], [fill="#FF0000"], [fill="#ff0000"],
  [fill="#f03"], [fill="#F03"], [fill="#FF0033"], [fill="#ff0033"], [fill="#FF0033FF"] {
    fill: var(--ctp-accent) !important;
  }
  ytd-topbar-logo-renderer [fill="white"], ytd-logo [fill="white"], #logo-icon [fill="white"] {
    fill: var(--ctp-crust) !important;
  }
  ytd-topbar-logo-renderer [fill="#282828"], ytd-topbar-logo-renderer [fill="#212121"],
  ytd-topbar-logo-renderer [fill="#FFFFFF"], ytd-topbar-logo-renderer [fill="#fff"] {
    fill: var(--ctp-text) !important;
  }

  /* Ambient mode glow (it tints the page with the video's colours). The newer watch page paints it
     with the ytCinematicContainerViewModel pieces: a blurred copy of the video behind the player. */
  #cinematics, #cinematic-container, #cinematics-container, #cinematics-full-bleed-container,
  .ytCinematicContainerViewModelBackgroundImage, .ytCinematicContainerViewModelFadeToThemeImage,
  [class*="ytCinematicContainerViewModel"] img, [class*="ytCinematicContainerViewModel"] canvas {
    display: none !important;
  }
  [class*="ytCinematicContainerViewModel"] {
    background: transparent !important;
  }

  /* On the watch page YouTube fades the top bar to transparent (opacity 0) so the ambient glow shows
     through. With the glow gone it has to be solid again, or the page scrolls visibly under it. */
  #background.ytd-masthead,
  ytd-masthead[is-watch-page] #background.ytd-masthead,
  ytd-masthead[is-shorts-page] #background.ytd-masthead {
    background: transparent !important;
