  .ytp-settings-button.ytp-8k-quality-badge::after,
  .ytp-chrome-controls .ytp-button[aria-pressed="true"]::after {
    background-color: var(--ctp-accent) !important;
  }
  .ytp-live-badge[disabled]::before, .ytp-live-badge::before { background: var(--ctp-accent) !important; }
  .ytp-autonav-toggle-button[aria-checked="true"] { background-color: var(--ctp-accent) !important; }
  .html5-video-player .ytp-sfn { background: color-mix(in srgb, var(--ctp-base) 85%, transparent) !important; color: var(--ctp-text) !important; }
  .ytp-sb-subscribe { background-color: var(--ctp-accent) !important; color: var(--ctp-crust) !important; }
  .ytp-sb-unsubscribe { background-color: var(--ctp-surface1) !important; color: var(--ctp-text) !important; }
  .ytp-ce-element .ytp-ce-expanding-overlay-background, .ytp-ce-element .ytp-ce-element-shadow {
    background-color: var(--ctp-mantle) !important;
  }

  /* Buttons */
  .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--filled,
  .ytSpecButtonShapeNextMono.ytSpecButtonShapeNextFilled {
    background-color: var(--ctp-text) !important;
    color: var(--ctp-crust) !important;
  }
  .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--tonal,
  .ytSpecButtonShapeNextMono.ytSpecButtonShapeNextTonal {
    background-color: var(--ctp-surface0) !important;
    color: var(--ctp-text) !important;
  }
  .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--tonal:hover,
  .ytSpecButtonShapeNextMono.ytSpecButtonShapeNextTonal:hover {
    background-color: var(--ctp-surface1) !important;
  }
  .yt-spec-button-shape-next--call-to-action.yt-spec-button-shape-next--filled,
  .ytSpecButtonShapeNextCallToAction.ytSpecButtonShapeNextFilled {
    background-color: var(--ctp-accent) !important;
    color: var(--ctp-crust) !important;
  }
  .yt-spec-button-shape-next--call-to-action.yt-spec-button-shape-next--text,
  .yt-spec-button-shape-next--call-to-action.yt-spec-button-shape-next--outline,
  .ytSpecButtonShapeNextCallToAction.ytSpecButtonShapeNextText,
  .ytSpecButtonShapeNextCallToAction.ytSpecButtonShapeNextOutline {
    color: var(--ctp-accent) !important;
  }

  /* Chips (All / Music / Gaming ...) */
  yt-chip-cloud-chip-renderer, .ytChipShapeChip, chip-shape, chip-shape button {
    border-radius: 8px !important;
  }
  yt-chip-cloud-chip-renderer, .ytChipShapeInactive, .ytChipShapeChip:not(.ytChipShapeActive) {
    background-color: var(--ctp-surface0) !important;
    color: var(--ctp-text) !important;
  }
  yt-chip-cloud-chip-renderer[selected], .ytChipShapeActive {
    background-color: var(--ctp-accent) !important;
    color: var(--ctp-crust) !important;
  }
  #chips-wrapper.ytd-feed-filter-chip-bar-renderer, ytd-feed-filter-chip-bar-renderer #chips-wrapper,
  ytd-feed-filter-chip-bar-renderer, .ytChipBarViewModelHost {
    background: transparent !important;
    backdrop-filter: none !important;
  }
  ytd-feed-filter-chip-bar-renderer #left-arrow::after, ytd-feed-filter-chip-bar-renderer #right-arrow::before,
  .ytChipBarViewModelLeftArrowContainer::after, .ytChipBarViewModelRightArrowContainer::before {
    background: none !important;
  }

  /* Search box and suggestions */
  .ytSearchboxComponentInputBox, .ytSearchboxComponentInputBoxDark, #container.ytd-searchbox {
    background: var(--ctp-base) !important;
    border-color: var(--ctp-surface1) !important;
    color: var(--ctp-text) !important;
    box-shadow: none !important;
  }
  .ytSearchboxComponentInputBoxHasFocus, .ytSearchboxComponentInputBoxHasFocusDark {
    border-color: var(--ctp-accent) !important;
  }
  .ytSearchboxComponentInput, input.ytSearchboxComponentInput, #search-input input {
    color: var(--ctp-text) !important;
  }
  .ytSearchboxComponentSearchButton, .ytSearchboxComponentSearchButtonDark, #search-icon-legacy {
    background: var(--ctp-surface0) !important;
    border-color: var(--ctp-surface1) !important;
    color: var(--ctp-text) !important;
  }
  .ytSearchboxComponentSuggestionsContainer, .ytSearchboxComponentSuggestionsContainerDark,
  .sbdd_b, .gstl_50.sbdd_a {
    background: var(--ctp-mantle) !important;
    border-color: var(--ctp-surface0) !important;
  }
  .ytSuggestionComponentHighlighted, .sbhl { background: var(--ctp-surface0) !important; }
  .ytSuggestionComponentSuggestion, .ytSuggestionComponentSuggestionDark, .sbqs_c { color: var(--ctp-text) !important; }

  /* Menus, dialogs, sheets */
  ytd-menu-popup-renderer, tp-yt-paper-listbox, ytd-multi-page-menu-renderer,
  .ytContextualSheetLayoutHost, .ytSpecDialogLayoutHost, tp-yt-paper-dialog,
  ytd-popup-container tp-yt-iron-dropdown #contentWrapper > * {
    background-color: var(--ctp-mantle) !important;
  }
  .ytListItemViewModelTappable:hover, tp-yt-paper-item:hover, ytd-menu-service-item-renderer:hover {
    background-color: var(--ctp-surface0) !important;
  }

  /* Description box, comments, chapters */
  ytd-watch-metadata {
    --yt-saturated-base-background: var(--ctp-base) !important;
    --yt-saturated-raised-background: var(--ctp-surface0) !important;
    --yt-saturated-additive-background: var(--ctp-surface0) !important;
    --yt-saturated-text-primary: var(--ctp-text) !important;
    --yt-saturated-text-secondary: var(--ctp-subtext0) !important;
    --yt-saturated-overlay-background: var(--ctp-surface0) !important;
    --yt-saturated-key-light: var(--ctp-surface1) !important;
  }
  #description.ytd-watch-metadata {
    background: var(--ctp-surface0) !important;
  }
  ytd-macro-markers-list-item-renderer {
    --ytd-macro-markers-list-item-background-color: var(--ctp-surface0) !important;
    --ytd-macro-markers-list-item-title-color: var(--ctp-text) !important;
    --ytd-macro-markers-list-item-secondary-color: var(--ctp-subtext1) !important;
    --ytd-macro-markers-list-item-timestamp-background-color: var(--ctp-surface1) !important;
  }
  ytd-playlist-panel-video-renderer, ytd-expandable-metadata-renderer, ytd-playlist-panel-renderer {
    --yt-lightsource-section1-color: var(--ctp-base) !important;
    --yt-lightsource-section2-color: var(--ctp-surface0) !important;
    --yt-lightsource-section3-color: var(--ctp-surface1) !important;
    --yt-lightsource-section4-color: var(--ctp-surface2) !important;
    --yt-lightsource-primary-title-color: var(--ctp-text) !important;
    --yt-lightsource-secondary-title-color: var(--ctp-subtext0) !important;
    --yt-active-playlist-panel-background-color: var(--ctp-surface0) !important;
  }
  .ytAttributedStringHighlightTextDecorator { background-color: var(--ctp-surface1) !important; }
  .ytAttributedStringLinkCallToActionColor, a.yt-simple-endpoint.yt-formatted-string { color: var(--ctp-accent) !important; }

  /* Thumbnails: badges and hover */
  .ytBadgeShapeThumbnailDefault, .ytBadgeShapeThumbnailDefaultRedesign,
  ytd-thumbnail-overlay-time-status-renderer, .badge-shape-wiz--thumbnail-default {
    background: color-mix(in srgb, var(--ctp-crust) 80%, transparent) !important;
    color: var(--ctp-text) !important;
  }
  .ytBadgeShapeThumbnailLive, ytd-thumbnail-overlay-time-status-renderer[overlay-style="LIVE"],
  .badge-style-type-live-now-alternate {
    background: var(--ctp-accent) !important;
    color: var(--ctp-crust) !important;
  }
  .ytSpecTouchFeedbackShapeHoverEffect { background-color: var(--ctp-surface0) !important; }

  /* Avatars: live ring */
  .ytSpecAvatarShapeLiveRing::after { background: var(--ctp-accent) !important; }
  .ytSpecAvatarShapeLiveBadge { background-color: var(--ctp-accent) !important; color: var(--ctp-crust) !important; }

  /* Notification badge */
  .ytSpecIconBadgeShapeTypeNotification .ytSpecIconBadgeShapeBadge, .yt-spec-icon-badge-shape__badge {
    background-color: var(--ctp-accent) !important;
    color: var(--ctp-crust) !important;
  }

  /* Switches */
  .ytSwitchShapeTrack { background-color: var(--ctp-surface2) !important; }
  .ytSwitchShapeTrackActive { background-color: var(--ctp-accent) !important; }
  .ytSwitchShapeKnob { background-color: var(--ctp-text) !important; }

  /* Loading skeletons */
  #home-page-skeleton, #guide-skeleton, #home-container-skeleton, #home-chips, .watch-skeleton {
    background-color: var(--ctp-base) !important;
  }
  #guide-skeleton .guide-ghost-icon, #guide-skeleton .guide-ghost-text, .masthead-skeleton-icon,
  #home-page-skeleton .skeleton-bg-color, .watch-skeleton .skeleton-bg-color, .skeleton-bg-color {
    background-color: var(--ctp-surface0) !important;
  }

  /* SponsorBlock segments, if the extension is installed */
  :root {
    --sb-category-sponsor: var(--ctp-green) !important;
    --sb-category-selfpromo: var(--ctp-yellow) !important;
    --sb-category-exclusive_access: var(--ctp-teal) !important;
    --sb-category-interaction: var(--ctp-mauve) !important;
    --sb-category-poi_highlight: var(--ctp-pink) !important;
    --sb-category-intro: var(--ctp-sky) !important;
    --sb-category-outro: var(--ctp-accent) !important;
    --sb-category-preview: var(--ctp-sapphire) !important;
    --sb-category-filler: var(--ctp-lavender) !important;
    --sb-category-music_offtopic: var(--ctp-peach) !important;
  }
}
